#include <cstdio>
#include <cstring>
#include <iostream>
using namespace std;

const int MAXN = 110000;
const int MOD = 1000000009;
long long dp[MAXN];

int main() {
    int n;
    scanf("%d", &n);

    dp[0] = 1;
    long long mulv = 2, ans = 6;

    for (int i = 1; i <= n / 2 - 2; i++) {
        mulv *= 2;
        mulv %= MOD;
        dp[i] = (dp[i - 1] + mulv) % MOD;
    }

    for (int i = 3; i <= n / 2; i++) {
        mulv = 1;
        for (int j = 1; j <= i - 2; j++) {
            mulv *= dp[j];
            mulv %= MOD;
        }
        ans += 4 * mulv;
        ans %= MOD;
    }

    ans = ans * ans % MOD + 1;
    ans *= 2;

    if (n != 2)
        printf("%lld", ans % MOD);
    else
        printf("10\n");

    return 0;
}

